{{define "app-directory-view-tabs"}} <nav class="apps-tabs" aria-label="{{.AppViews}}"><a href="/settings/apps" {{if .DiscoverCurrent}}aria-current="page"{{end}}>{{.Discover}}</a><a href="/settings/apps?view=connected" {{if .ConnectedCurrent}}aria-current="page"{{end}}>{{.YourApps}}</a><a href="/settings/apps?view=all" {{if .DirectoryCurrent}}aria-current="page"{{end}}>{{.AllApps}}</a></nav>
{{end}}
{{define "app-directory-view-collection-back"}} {{if .CollectionPresent}}<a class="back-link" href="/settings/apps">{{.BackToApps}}</a>{{end}}
{{end}}
{{define "app-directory-view-categories"}} {{if .CategoriesPresent}}<form method="get" action="/settings/apps" class="apps-filter" data-app-category-form><input type="hidden" name="view" value="all"><input type="hidden" name="search" value="{{.Search}}"><label for="app-category" class="sr-only">{{.CategoryLabel}}</label><select id="app-category" name="category"><option value="">{{.AllCategories}}</option>{{.Options}}</select><noscript><button class="secondary">{{.Filter}}</button></noscript></form>{{end}}
{{end}}
{{define "app-directory-view-pagination"}} {{if .PaginationPresent}}<a class="button secondary" href="/settings/apps?view=all&amp;search={{.Search}}&amp;category={{.Category}}&amp;cursor={{.NextCursor}}">{{.MoreApps}}</a>{{end}}
{{end}}
{{define "app-directory-view-option"}}<option value="{{.OptionID}}" {{if .OptionSelected}}selected{{end}}>{{.OptionName}}</option>{{end}}
